import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getMeetings } from '../api';

function Dashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMeetings = async () => {
      try {
        const res = await getMeetings();
        setMeetings(res.data);
      } catch (err) {
        console.error('Error loading meetings:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchMeetings();
  }, []);

  // Calculate statistics
  const scheduled = meetings.filter(m => m.status === 'scheduled').length;
  const completed = meetings.filter(m => m.status === 'completed').length;
  const cancelled = meetings.filter(m => m.status === 'cancelled').length;

  // Upcoming meetings (next 5)
  const upcoming = meetings
    .filter(m => m.status === 'scheduled' && new Date(m.date) >= new Date())
    .slice(0, 5);

  if (loading) return <div className="loading">Loading dashboard...</div>;

  const statCardStyle = {
    background: 'white',
    borderRadius: '12px',
    padding: '1.5rem',
    textAlign: 'center',
    boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
  };

  return (
    <div className="page">
      <h1>👋 Welcome, {user.name}!</h1>

      {/* Stats Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1rem', marginBottom: '2rem' }}>
        <div style={statCardStyle}>
          <div style={{ fontSize: '2rem', fontWeight: '700', color: '#2563eb' }}>{scheduled}</div>
          <div style={{ color: '#64748b', marginTop: '0.3rem' }}>Scheduled</div>
        </div>
        <div style={statCardStyle}>
          <div style={{ fontSize: '2rem', fontWeight: '700', color: '#16a34a' }}>{completed}</div>
          <div style={{ color: '#64748b', marginTop: '0.3rem' }}>Completed</div>
        </div>
        <div style={statCardStyle}>
          <div style={{ fontSize: '2rem', fontWeight: '700', color: '#ef4444' }}>{cancelled}</div>
          <div style={{ color: '#64748b', marginTop: '0.3rem' }}>Cancelled</div>
        </div>
      </div>

      {/* Upcoming Meetings */}
      <div className="card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <h2 style={{ margin: 0 }}>📅 Upcoming Meetings</h2>
          <Link to="/meetings" style={{ color: '#2563eb', fontSize: '0.9rem', textDecoration: 'none' }}>
            View all →
          </Link>
        </div>

        {upcoming.length === 0 ? (
          <p style={{ color: '#64748b', textAlign: 'center', padding: '1rem' }}>
            No upcoming meetings scheduled.
          </p>
        ) : (
          upcoming.map(meeting => (
            <Link
              key={meeting._id}
              to={`/meetings/${meeting._id}`}
              style={{ textDecoration: 'none' }}
            >
              <div style={{
                padding: '1rem',
                borderRadius: '8px',
                border: '1px solid #e2e8f0',
                marginBottom: '0.7rem',
                transition: 'background 0.2s',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}
                onMouseEnter={e => e.currentTarget.style.background = '#f8fafc'}
                onMouseLeave={e => e.currentTarget.style.background = 'white'}
              >
                <div>
                  <div style={{ fontWeight: '600', color: '#1e293b' }}>{meeting.title}</div>
                  <div style={{ fontSize: '0.85rem', color: '#64748b', marginTop: '0.2rem' }}>
                    📍 {meeting.venue} &nbsp;•&nbsp; 🕐 {meeting.time}
                  </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div style={{ fontSize: '0.85rem', color: '#64748b' }}>
                    {new Date(meeting.date).toLocaleDateString('en-IN', {
                      day: 'numeric', month: 'short', year: 'numeric'
                    })}
                  </div>
                </div>
              </div>
            </Link>
          ))
        )}
      </div>

      {/* Quick Actions for Admin */}
      {user.role === 'admin' && (
        <div className="card">
          <h2>⚡ Quick Actions</h2>
          <Link to="/create-meeting">
            <button className="btn btn-primary">+ Schedule New Meeting</button>
          </Link>
        </div>
      )}
    </div>
  );
}

export default Dashboard;
